# Development
Work in this checkout and keep tests offline and deterministic.
Run `node --test tests/*.test.mjs`. Preserve public interfaces and existing tests.
Do not modify dependency/build configuration or inspect benchmark
machinery, grading artifacts or files outside this repository.
import test from "node:test";
import assert from "node:assert/strict";
import * as core0 from "../src/numeric_median.ts";
test("numeric-median",()=>{assert.equal(core0.median([1,2,3]),2);});
import * as core1 from "../src/chunk_without_empty_tail.ts";
test("chunk-without-empty-tail",()=>{assert.deepEqual(core1.chunk([1,2,3],2),[[1,2],[3]]);});
import * as core2 from "../src/signed_code_padding.ts";
import * as api2 from "../src/signed_code_padding_api.ts";
test("signed-code-padding",()=>{assert.equal(api2.labelCode(7,3),"007");});
import * as core3 from "../src/equal_length_zip.ts";
import * as api3 from "../src/equal_length_zip_api.ts";
test("equal-length-zip",()=>{assert.deepEqual(api3.pairTable({name:"label",values:["a","b"]},{name:"count",values:[1,2]}),{headers:["label","count"],rows:[["a",1],["b",2]]});});
import * as core4 from "../src/zero_count_plural.ts";
test("zero-count-plural",()=>{assert.equal(core4.pluralize(2,"item","items"),"items");});
